CREATE OR REPLACE FUNCTION public.pro_access_window_open(_visit uuid,_pro uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.visits v WHERE v.id=_visit AND public.pro_on_cleaning_team_visit(v.id,_pro) AND v.scheduled_start IS NOT NULL AND now() >= v.scheduled_start - interval '30 minutes' AND v.status::text IN ('scheduled','on_the_way','in_progress') AND v.check_out_at IS NULL AND NOT EXISTS(SELECT 1 FROM public.cleaning_team_presence p WHERE p.visit_id=v.id AND p.pro_id=_pro AND p.check_out_at IS NOT NULL)) $$;
REVOKE ALL ON FUNCTION public.pro_access_window_open(uuid,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.pro_access_window_open(uuid,uuid) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.pro_get_visits(_from date DEFAULT (CURRENT_DATE-60),_to date DEFAULT (CURRENT_DATE+60)) RETURNS TABLE(id uuid,scheduled_start timestamptz,scheduled_end timestamptz,service_type text,street text,zip text,customer_first_name text,access_notes text,gate_code text,pet_notes text,parking_notes text,visit_pay_cents integer,status text,on_my_way_at timestamptz,completed_at timestamptz,is_sample boolean,before_photos integer,after_photos integer,visit_kind text,paid_in_full_reason text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT v.id,v.scheduled_start,v.scheduled_end,v.service_type,v.street,v.zip,v.customer_first_name,CASE WHEN public.pro_access_window_open(v.id,auth.uid()) THEN public.access_decrypt(v.access_notes_enc) END,CASE WHEN public.pro_access_window_open(v.id,auth.uid()) THEN public.access_decrypt(v.gate_code_enc) END,v.pet_notes,v.parking_notes,CASE WHEN v.service::text='cleaning' THEN public.cleaning_pro_visit_pay(v.id,auth.uid()) ELSE v.visit_pay_cents END,v.status::text,v.on_my_way_at,v.completed_at,v.is_sample,(SELECT count(*)::integer FROM public.visit_photos p WHERE p.visit_id=v.id AND p.kind='before'),(SELECT count(*)::integer FROM public.visit_photos p WHERE p.visit_id=v.id AND p.kind='after'),v.visit_kind,v.paid_in_full_reason FROM public.visits v WHERE public.pro_on_cleaning_team_visit(v.id,auth.uid()) AND (v.scheduled_start IS NULL OR (v.scheduled_start AT TIME ZONE 'America/New_York')::date BETWEEN _from AND _to) ORDER BY v.scheduled_start NULLS LAST,v.id $$;
CREATE OR REPLACE FUNCTION public.pro_route_details() RETURNS TABLE(visit_id uuid,size_tier smallint,is_lead boolean,is_team boolean,first_visit boolean,checked_in boolean,checked_out boolean) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT v.id,v.size_tier,v.assigned_pro_id=auth.uid(),v.size_tier=5 AND v.service::text='cleaning',v.cleaning_first_visit,CASE WHEN v.assigned_pro_id=auth.uid() THEN v.check_in_at IS NOT NULL ELSE EXISTS(SELECT 1 FROM public.cleaning_team_presence p WHERE p.visit_id=v.id AND p.pro_id=auth.uid() AND p.check_in_at IS NOT NULL) END,CASE WHEN v.assigned_pro_id=auth.uid() THEN v.check_out_at IS NOT NULL ELSE EXISTS(SELECT 1 FROM public.cleaning_team_presence p WHERE p.visit_id=v.id AND p.pro_id=auth.uid() AND p.check_out_at IS NOT NULL) END FROM public.visits v WHERE public.pro_on_cleaning_team_visit(v.id,auth.uid()) AND (v.scheduled_start IS NULL OR (v.scheduled_start AT TIME ZONE 'America/New_York')::date BETWEEN CURRENT_DATE-60 AND CURRENT_DATE+60) $$;
REVOKE ALL ON FUNCTION public.pro_route_details() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.pro_route_details() TO authenticated;
CREATE OR REPLACE FUNCTION public.pro_visit_extras(_visit uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE v public.visits; vehicle jsonb; BEGIN SELECT * INTO v FROM public.visits WHERE id=_visit; IF NOT FOUND OR NOT public.pro_on_cleaning_team_visit(v.id,auth.uid()) THEN RETURN NULL; END IF; IF v.visit_kind='car_wash' THEN SELECT jsonb_build_object('vehicle_make',c.vehicle_make,'vehicle_model',c.vehicle_model,'vehicle_color',c.vehicle_color,'parking_spot',c.parking_spot,'interior_included',c.interior_included,'interior_access',CASE WHEN public.pro_access_window_open(v.id,auth.uid()) THEN c.interior_access END) INTO vehicle FROM public.car_wash_profiles c WHERE c.subscription_id=v.subscription_id; END IF; RETURN jsonb_build_object('addons',coalesce((SELECT jsonb_agg(jsonb_build_object('name',a.addon_name,'status',a.status) ORDER BY a.attached_at) FROM public.addon_attaches a WHERE a.visit_id=v.id AND a.status<>'removed'),'[]'::jsonb),'car_wash',vehicle); END $$;